function currentSceneAssets(){const seconds=t*settings.duration,d=phaseTimes();if(seconds>=d.noir&&seconds<d.images)return base.querySelector('.continuation')?.sceneAssets||[];if(seconds>=d.fire&&seconds<d.outdoor)return [{id:'room-fire',kind:'roomFire',name:'Desk fire',rect:[0,0,960,540],bounds:{x:0,y:0,w:960,h:540},matrix:{a:1,b:0,c:0,d:1,e:0,f:0},corners:[{x:0,y:0},{x:960,y:0},{x:960,y:540},{x:0,y:540}]}];return []}
function clearSceneSelection(){selectedSceneAsset=null;selectionSVG.replaceChildren();selectionTools.hidden=true;selectionTools.replaceChildren()}
function drawSceneSelection(){if(!selectedSceneAsset)return;const asset=currentSceneAssets().find(a=>a.id===selectedSceneAsset.id);if(!asset){clearSceneSelection();return}selectedSceneAsset=asset;selectionSVG.replaceChildren();const polygon=document.createElementNS(selectionSVG.namespaceURI,'polygon');polygon.setAttribute('points',asset.corners.map(p=>p.x+','+p.y).join(' '));selectionSVG.append(polygon);for(const p of asset.corners){const corner=document.createElementNS(selectionSVG.namespaceURI,'rect');corner.setAttribute('x',p.x-4);corner.setAttribute('y',p.y-4);corner.setAttribute('width',8);corner.setAttribute('height',8);selectionSVG.append(corner)}}
function selectSceneAsset(asset){selectedSceneAsset=asset;selectionTools.hidden=false;playing=false;document.querySelector('#play').textContent='▶';renderAssetContext();drawSceneSelection()}
base.addEventListener('click',e=>{if(!editor.open||battleMuzzlePick||chessEditing)return;const assets=currentSceneAssets();if(!assets.length){if(selectedSceneAsset)clearSceneSelection();return}const r=base.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*960,y=(e.clientY-r.top)/r.height*540;const hits=sceneGeometry?assets.filter(a=>sceneGeometry.hitSceneAsset(a,x,y)).reverse():[];e.preventDefault();e.stopImmediatePropagation();if(!hits.length||selectedSceneAsset?.id===hits[0].id){clearSceneSelection();return}selectSceneAsset(hits[0])},true);
