function keyframeTools(host,target,keys,age){const row=document.createElement('div');row.className='contextActions';host.append(row);toolButton(row,'Set keyframe here',()=>{const at=Math.round(age()*100)/100,key={at};for(const k of keys)key[k]=target[k];target.keys||=[];const i=target.keys.findIndex(k=>Math.abs(k.at-at)<.02);if(i<0)target.keys.push(key);else target.keys[i]=key;target.keys.sort((a,b)=>a.at-b.at);assetSave();renderAssetContext()});toolButton(row,'Clear motion keys',()=>{target.keys=[];assetSave();renderAssetContext()});const note=document.createElement('span');note.className='sub';note.textContent=(target.keys||[]).map(k=>k.at+'s').join(' · ')||'No motion keys';row.append(note)}
