if(a.kind==='soldier'){const p=fx.battleSoldiers[a.soldierIndex];toolNumbers(host,p,[['x','Position X',-500,1400,1],['y','Position Y',-300,900,1],['width','Width',30,1000,1],['rotation','Rotation',-180,180,1],['blur','Softness',0,20,.1],['opacity','Opacity',0,1,.05],['muzzleU','Muzzle X',0,1,.005],['muzzleV','Muzzle Y',0,1,.005]]);keyframeTools(selectionTools,p,['x','y','width','rotation','opacity'],battleAge);toolButton(selectionTools,'Place muzzle…',()=>{battleSoldierIndex=a.soldierIndex;selectEffect('battle',false);document.querySelector('#battleMuzzlePick')?.click()});mediaTools(selectionTools,a)}
if(a.kind==='men'){toolNumbers(host,fx,[['noirMenX','Position X',-500,1000,1],['noirMenY','Position Y',-500,1000,1],['noirMenScale','Scale',.1,3,.05],['noirMenRotation','Rotation',-180,180,1],['noirStartScale','Parallax start size',.4,2,.05],['noirEndScale','Parallax end size',.4,2,.05],['noirReveal','Parallax duration',3,22,.1]]);mediaTools(selectionTools,a)}
